/* Какие выборы класса нужны на 1 уровне (отдельный шаг визарда). */
function classChoiceNeeds(classId){
  const cc = (typeof state !== "undefined" && state.classChoices) || {};
  if (SUBCLASSES[classId]){
    const sub = SUBCLASSES[classId].find(x => x.id === cc.subclass);
    const needs = ["subclass", ...((sub && sub.needs) || [])];
    if (classId === "cleric" && sub) needs.push("deity");
    if (classId === "warlock"){
      if (sub) needs.push("deity");
      needs.push("pactBoon");
      const extra = { tome:"pactTome", blade:"pactBlade", chain:"pactChain" }[cc.pactBoon];
      if (extra) needs.push(extra);
    }
    return needs;
  }
  if (classId === "paladin") return ["deity"];
  if (classId === "fighter") return ["fightingStyle"];
  if (classId === "ranger")  return ["favoredEnemy","favoredTerrain"];
  if (classId === "rogue")   return ["expertise"];
  return [];
}

/* Классовые умения 1 уровня с подставленными числами.
   kind: passive | action | bonus | reaction; uses — число кружков для отметки на бумаге;
   rest — когда восстанавливается. */
function classSheetFeatures(classId, d){
  const m = d.mods, pb = d.pb, cc = d.classChoices || {};
  const f = [];
  const add = (name, text, extra) => f.push(Object.assign({ name, text, kind:"passive" }, extra||{}));
  const addSubclass = () => {
    const sub = getSubclass(classId, cc);
    if (!sub){ add(SUBCLASS_TITLE[classId], "Не выбрано: ______________________"); return; }
    add(`${SUBCLASS_TITLE[classId]}: ${sub.name}`, sub.text);
    (sub.features || []).forEach(ft => {
      const uses = typeof ft.uses === "function" ? ft.uses(m, pb) : ft.uses;
      const text = typeof ft.text === "function" ? ft.text(m, pb, cc) : ft.text;
      add(ft.name, text, { kind: ft.kind || "passive", uses, rest: ft.rest });
    });
  };
  switch(classId){
    case "barbarian":
      add("Ярость", "Бонусным действием, если не носите тяжёлый доспех. 1 минуту: преимущество на проверки и спасброски Силы; +2 к урону рукопашным оружием на Силе; сопротивление дробящему, колющему и рубящему урону. Нельзя накладывать и поддерживать заклинания. Заканчивается раньше, если вы потеряли сознание или за ход не атаковали враждебное существо и не получили урон.", { kind:"bonus", uses:2, rest:"продолжительный отдых" });
      add("Защита без доспехов", `Без доспеха КД = 10 + мод. Ловкости + мод. Телосложения = ${10 + m.dex + m.con}. Щит можно использовать.`);
      break;
    case "bard":
      add("Вдохновение барда", "Бонусным действием выберите существо в пределах 60 футов (не себя), которое вас слышит: оно получает кость вдохновения к6. В течение 10 минут оно может добавить её к одной проверке, броску атаки или спасброску.", { kind:"bonus", uses:Math.max(1, m.cha), rest:"продолжительный отдых" });
      break;
    case "cleric":
      addSubclass();
      break;
    case "druid":
      add("Друидический язык", "Вы знаете тайный язык друидов: можете говорить на нём и оставлять скрытые послания. Остальные замечают послание при успешной проверке Мудрости (Восприятие) Сл 15, но не могут его прочесть без магии.");
      break;
    case "fighter": {
      const st = FIGHTING_STYLES.find(s => s.id === cc.fightingStyle);
      add("Боевой стиль" + (st ? ": " + st.name : ""), st ? st.text : "Выберите стиль: ______________________");
      add("Второе дыхание", "Бонусным действием восстановите 1к10 + 1 (уровень воина) хитов.", { kind:"bonus", uses:1, rest:"короткий или продолжительный отдых" });
      break;
    }
    case "monk":
      add("Защита без доспехов", `Без доспеха и щита КД = 10 + мод. Ловкости + мод. Мудрости = ${10 + m.dex + m.wis}.`);
      add("Боевые искусства", `Без доспеха и щита, безоружным ударом или монашеским оружием (короткий меч и простое рукопашное оружие без свойств «тяжёлое» и «двуручное»): можно использовать Ловкость вместо Силы для атаки и урона; урон безоружного удара — к4; после действия Атака можно бонусным действием совершить один безоружный удар. Безоружный удар: попадание ${fmtMod(Math.max(m.str, m.dex) + pb)}, урон 1к4${fmtMod(Math.max(m.str, m.dex))} дробящий.`, { kind:"bonus" });
      break;
    case "paladin":
      add("Божественное чувство", "Действием до конца вашего следующего хода вы знаете местоположение любого небожителя, исчадия или нежити в пределах 60 футов, не находящегося за полным укрытием, а также освящённые и осквернённые места и предметы.", { kind:"action", uses:1 + Math.max(0, m.cha), rest:"продолжительный отдых" });
      add("Наложение рук", "Запас целительной силы — 5 хитов (5 × уровень паладина). Действием коснитесь существа и восстановите ему хиты из запаса. Можно потратить 5 хитов из запаса, чтобы вылечить одну болезнь или нейтрализовать один яд. Не действует на нежить и конструктов. Запас: ☐☐☐☐☐", { kind:"action", rest:"продолжительный отдых" });
      break;
    case "ranger":
      add("Избранный враг" + (cc.favoredEnemy ? ": " + cc.favoredEnemy : ""), "Преимущество на проверки Мудрости (Выживание) для выслеживания избранных врагов и на проверки Интеллекта, чтобы вспомнить информацию о них. Вы также знаете один язык, на котором говорят ваши избранные враги." + (cc.favoredEnemy ? "" : " Тип врага: ______________________"));
      add("Исследователь природы" + (cc.favoredTerrain ? ": " + cc.favoredTerrain : ""), "В излюбленной местности: удвоенный бонус мастерства к проверкам Интеллекта и Мудрости, связанным с ней; труднопроходимая местность не замедляет группу; группа не может заблудиться без магии; вы всегда настороже; в одиночку можно красться в обычном темпе; при поиске пищи находите вдвое больше; при выслеживании узнаёте число, размер и давность прохода существ." + (cc.favoredTerrain ? "" : " Местность: ______________________"));
      break;
    case "rogue": {
      const ex = (cc.expertise || []).filter(Boolean);
      add("Компетентность", "Ваш бонус мастерства удваивается для выбранных навыков" + (ex.length ? `: ${ex.join(", ")}` : " (два навыка или один навык и воровские инструменты): ______________"));
      add("Скрытая атака", "Раз в ход вы можете нанести дополнительно 1к6 урона существу, по которому попали атакой, если у вас было преимущество на бросок атаки. Атака должна совершаться фехтовальным или дальнобойным оружием. Преимущество не нужно, если в пределах 5 футов от цели есть другой ваш враг, который не недееспособен, и у вас нет помехи на бросок атаки.");
      add("Воровской жаргон", "Тайная смесь диалекта, жаргона и шифра: можно прятать послания в обычном разговоре и понимать тайные знаки и символы. Передача послания занимает вчетверо больше времени, чем обычная речь.");
      break;
    }
    case "sorcerer":
      addSubclass();
      break;
    case "warlock":
      addSubclass();
      pactBoonFeature(m, pb, cc).forEach(x => add(x.name, x.text, x.extra));
      break;
    case "wizard":
      add("Магическое восстановление", "Раз в день, во время короткого отдыха, вы можете восстановить потраченные ячейки заклинаний с суммарным уровнем не больше половины уровня волшебника (округляя вверх) — на 1-м уровне это одна ячейка 1-го уровня.", { uses:1, rest:"продолжительный отдых" });
      add("Книга заклинаний", "Заклинания волшебника записаны в книге. Подготовленных заклинаний в день: мод. Интеллекта + уровень (минимум 1). Ритуалы из книги можно накладывать без подготовки.");
      break;
  }
  const dz = deitySheetFeature(classId, cc);
  if (dz) add(dz.name, dz.text);
  return f;
}

