/* ===== Атаки: разбор строки info из каталога снаряжения ===== */
/* Возвращает null, если предмет не оружие. */
function parseWeapon(item){
  const name = item.name || item;
  const info = item.info || "";
  const m = info.match(/(?:по\s+)?(\d+d\d+)\s+(колющий|рубящий|дробящий)/);
  if (!m) return null;
  const props = info.toLowerCase();
  const ranged = /боеприпасы/.test(props) || /праща|лук|арбалет/i.test(name);
  const thrown = /бросковое/.test(props);
  const finesse = /фехтовальное/.test(props);
  const versatile = (info.match(/универсальное\s*\((\d+d\d+)/) || [])[1] || null;
  const range = (info.match(/(\d+\/\d+)/) || [])[1] || null;
  return { name, dice: m[1].replace("d","к"), type: m[2], ranged, thrown, finesse, versatile: versatile ? versatile.replace("d","к") : null, range, light: /лёгкое/.test(props), twoHanded: /двуручное/.test(props) };
}

/* Стартовые комплекты классов и свободная сборка (вариант D) уже ограничены оружием,
   которым класс владеет, поэтому бонус мастерства к атаке добавляется всегда. */
function buildAttacks(d){
  const { mods, pb, c, equip } = d;
  const cc = d.classChoices || {};
  const out = [];
  const monk = c && c.id === "monk";
  (equip && equip.items || []).forEach(it => {
    const w = parseWeapon(it);
    if (!w) return;
    let ab = "str";
    if (w.ranged) ab = "dex";
    else if (w.finesse || (monk && !w.twoHanded)) ab = mods.dex > mods.str ? "dex" : "str";
    let hit = mods[ab] + pb;
    let dmgBonus = mods[ab];
    if (cc.fightingStyle === "archery" && w.ranged) hit += 2;
    if (cc.fightingStyle === "dueling" && !w.ranged && !w.twoHanded) dmgBonus += 2;
    const dice = w.dice;
    const notes = [];
    if (w.versatile) notes.push(`двумя руками ${w.versatile}${fmtMod(mods[ab])}`);
    if (w.range) notes.push(`дистанция ${w.range} фт`);
    if (c && c.id === "rogue" && (w.finesse || w.ranged)) notes.push("+1к6 скрытая атака");
    if (c && c.id === "barbarian" && !w.ranged && ab === "str") notes.push("+2 в ярости");
    out.push({ name: w.name, hit: fmtMod(hit), dmg: `${dice}${dmgBonus ? fmtMod(dmgBonus) : ""} ${w.type}`, notes: notes.join(", ") });
  });
  // Безоружный удар — есть у всех.
  if (monk) out.push({ name: "Безоружный удар", hit: fmtMod(Math.max(mods.str, mods.dex) + pb), dmg: `1к4${fmtMod(Math.max(mods.str, mods.dex))} дробящий`, notes: "боевые искусства, можно бонусным действием" });
  else if (!(d.raceAttacks || []).some(a => /безоружный удар/.test(a.notes || ""))) out.push({ name: "Безоружный удар", hit: fmtMod(mods.str + pb), dmg: `${Math.max(0, 1 + mods.str)} дробящий`, notes: "" });
  (d.raceAttacks || []).forEach(a => out.push(a));
  return out;
}


